fn main() {
    // the application icon, shown in Explorer (generated by assets/make_logo.py)
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        println!("cargo:rerun-if-changed=parapet.rc");
        println!("cargo:rerun-if-changed=assets/parapet.ico");
        let _ = embed_resource::compile("parapet.rc", embed_resource::NONE);
    }
}
